"use client";

import { useState } from "react";
import { PlayToggle } from "@/components/audio-ui/play-toggle";
import { GatePanel } from "@/components/audio-ui/devices/gate/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import {
  type GateState,
  gateDevice,
} from "@/components/audio-ui/devices/gate/device";
import { createGateEngine } from "@/components/audio-ui/devices/gate/engine";

const MASTER_VOLUME = 0.7;

/**
 * A gate you can plug in: its state, a panel that draws its transfer curve with a handle on the threshold and an engine that plays it, each its own file. Play the loop and raise the threshold: the quiet parts go.
 */
export function BlockGate() {
  const [state, setState] = useState<GateState>(() => gateDevice.defaults());
  const master = useMasterBus(MASTER_VOLUME);
  const { playing, toggle } = useDeviceLoop({
    create: createGateEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-none h-full w-full min-w-0">
      <GatePanel onValueChange={setState} value={state}>
        <PlayToggle
          label="Play a loop through it"
          onToggle={toggle}
          playing={playing}
        />
      </GatePanel>
    </div>
  );
}
